import type { ComponentProps, JSX } from '@solidjs/web'
import {
  PasswordInput as UiPasswordInput,
  PasswordInputControl as UiPasswordInputControl,
  PasswordInputToggle as UiPasswordInputToggle,
  type PasswordInputState,
} from '@ui-sdk/solid/password-input'
import { omit, Show } from 'solid-js'

import './password-input.css'

export { createPasswordInputController } from '@ui-sdk/solid/password-input'
export type {
  InputValueChangeReason,
  PasswordInputController,
  PasswordInputOptions,
  PasswordInputPrimitive,
  PasswordInputState,
  PasswordInputVisibleChangeReason,
} from '@ui-sdk/solid/password-input'

export type PasswordInputAppearance = 'small' | 'base' | 'large'
export type PasswordInputSurface = 'base' | 'layer-1' | 'invisible'

type UiPasswordInputProps = ComponentProps<typeof UiPasswordInput>

export type PasswordInputProps = Omit<
  UiPasswordInputProps,
  'class' | 'render' | 'children'
> & {
  /** Field height: `small` (24px), `base` (28px, default), or `large` (32px). */
  appearance?: PasswordInputAppearance
  /** Background fill. Defaults to `base`. */
  surface?: PasswordInputSurface
  /** Marks the outline and text red. */
  invalid?: boolean
  /** Optional icon rendered before the field. */
  leadingIcon?: JSX.Element
  class?: UiPasswordInputProps['class']
  render?: UiPasswordInputProps['render']
  children?: UiPasswordInputProps['children']
}

export function PasswordInput(props: PasswordInputProps) {
  const rest = omit(
    props,
    'appearance',
    'surface',
    'invalid',
    'leadingIcon',
    'class',
    'render',
    'children',
  )

  return (
    <UiPasswordInput
      {...rest}
      class={props.class}
      render={props.render}
      data-appearance={props.appearance ?? 'base'}
      data-surface={props.surface ?? 'base'}
      data-invalid={props.invalid ? '' : undefined}
      data-leading-icon={props.leadingIcon ? '' : undefined}
    >
      {(state: PasswordInputState) => (
        <>
          <Show when={props.leadingIcon}>
            <span data-slot="password-input-leading-icon">
              {props.leadingIcon}
            </span>
          </Show>
          {typeof props.children === 'function'
            ? props.children(state)
            : props.children}
        </>
      )}
    </UiPasswordInput>
  )
}

type UiPasswordInputControlProps = ComponentProps<typeof UiPasswordInputControl>

export type PasswordInputControlProps = Omit<
  UiPasswordInputControlProps,
  'class' | 'render'
> & {
  /** Marks the native input invalid for assistive tech. */
  invalid?: boolean
  class?: UiPasswordInputControlProps['class']
  render?: UiPasswordInputControlProps['render']
}

export function PasswordInputControl(props: PasswordInputControlProps) {
  const rest = omit(props, 'invalid', 'class', 'render')

  return (
    <UiPasswordInputControl
      {...rest}
      class={props.class}
      render={props.render}
      aria-invalid={props.invalid ? 'true' : props['aria-invalid']}
    />
  )
}

function EyeIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      width={14}
      height={14}
      fill="none"
      stroke="currentColor"
      stroke-width={1.25}
      stroke-linecap="round"
      stroke-linejoin="round"
      aria-hidden="true"
    >
      <path d="M1.75 8s2.25-4 6.25-4 6.25 4 6.25 4-2.25 4-6.25 4S1.75 8 1.75 8Z" />
      <circle cx="8" cy="8" r="1.75" />
    </svg>
  )
}

function EyeOffIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      width={14}
      height={14}
      fill="none"
      stroke="currentColor"
      stroke-width={1.25}
      stroke-linecap="round"
      stroke-linejoin="round"
      aria-hidden="true"
    >
      <path d="M6.7 4.2A6.6 6.6 0 0 1 8 4c4 0 6.25 4 6.25 4a11.3 11.3 0 0 1-1.9 2.35" />
      <path d="M9.3 9.3a1.75 1.75 0 0 1-2.6-2.6" />
      <path d="M10.7 11.5A6.7 6.7 0 0 1 8 12c-4 0-6.25-4-6.25-4a11.5 11.5 0 0 1 2.75-3" />
      <path d="m2 2 12 12" />
    </svg>
  )
}

type UiPasswordInputToggleProps = ComponentProps<typeof UiPasswordInputToggle>

export type PasswordInputToggleProps = Omit<
  UiPasswordInputToggleProps,
  'class' | 'render' | 'children'
> & {
  class?: UiPasswordInputToggleProps['class']
  render?: UiPasswordInputToggleProps['render']
  children?: UiPasswordInputToggleProps['children']
}

export function PasswordInputToggle(props: PasswordInputToggleProps) {
  const rest = omit(props, 'class', 'render', 'children')

  return (
    <UiPasswordInputToggle
      {...rest}
      class={props.class}
      render={props.render}
    >
      {(state: PasswordInputState) => {
        if (props.children !== undefined) {
          return typeof props.children === 'function'
            ? props.children(state)
            : props.children
        }
        return state.visible ? <EyeOffIcon /> : <EyeIcon />
      }}
    </UiPasswordInputToggle>
  )
}

@layer components {
  /* Matches input.css [data-slot="input-group"] 1:1 */
  [data-slot="password-input"] {
    box-sizing: border-box;
    display: flex;
    flex-direction: row;
    align-items: stretch;
    padding-block: 0;
    padding-inline: 0 6px;
    gap: 6px;
    width: 280px;
    max-width: 100%;
    height: 28px;
    border: 0;
    border-radius: 6px;
    outline: 1px solid transparent;
    outline-offset: -1px;
    background: var(--v2-background-bg-base);
    box-shadow: var(--v2-elevation-input);
    flex: none;
    align-self: stretch;
    transition:
      background 85ms ease-out,
      outline-color 85ms ease-out,
      box-shadow 85ms ease-out;
  }

  [data-slot="password-input"][data-appearance="small"] {
    height: 24px;
  }

  [data-slot="password-input"][data-appearance="large"] {
    height: 32px;
  }

  [data-slot="password-input"][data-surface="layer-1"] {
    background: var(--v2-background-bg-layer-01);
  }

  [data-slot="password-input"][data-surface="invisible"] {
    background: transparent;
    box-shadow: none;
  }

  @media (hover: hover) {
    [data-slot="password-input"]:hover:not(
        [data-disabled],
        [data-invalid],
        [data-surface="invisible"]
      ):not(:has([data-slot="password-input-control"]:focus)):not(
        :has([data-invalid])
      ) {
      box-shadow:
        inset 0 0 0 100vmax var(--v2-overlay-simple-overlay-hover),
        var(--v2-elevation-input);
    }

    [data-slot="password-input"][data-surface="invisible"]:hover:not(
        [data-disabled],
        [data-invalid]
      ):not(:has([data-slot="password-input-control"]:focus)):not(
        :has([data-invalid])
      ) {
      background: var(--v2-overlay-simple-overlay-hover);
    }
  }

  [data-slot="password-input"]:has(
      [data-slot="password-input-control"]:focus
    ):not([data-disabled], [data-invalid]):not(:has([data-invalid])) {
    outline-color: var(--v2-border-border-focus);
    box-shadow: none;
  }

  [data-slot="password-input"][data-invalid]:not([data-disabled]),
  [data-slot="password-input"]:has(
      [data-slot="password-input-control"]:is(
          [data-invalid],
          [aria-invalid="true"]
        )
    ):not([data-disabled]) {
    outline-color: var(--v2-state-fg-danger);
    box-shadow: none;
  }

  [data-slot="password-input"][data-disabled] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* ---------------------------------------------------------------- */
  /* Control                                                          */
  /* ---------------------------------------------------------------- */

  [data-slot="password-input-control"] {
    display: block;
    width: 100%;
    min-width: 0;
    flex: 1 1 auto;
    min-height: 0;
    height: 100%;
    padding-block: 0;
    padding-inline: 8px 0;
    margin: 0;
    border: 0;
    background: transparent;
    outline: none;
    font-style: normal;
    font-weight: 440;
    font-size: 13px;
    line-height: var(--line-height-compact);
    letter-spacing: -0.04px;
    color: var(--v2-text-text-base);
    font-variation-settings: "slnt" 0;
  }

  [data-slot="password-input"][data-leading-icon]
    [data-slot="password-input-control"] {
    padding-inline-start: 0;
  }

  [data-slot="password-input-control"]::placeholder {
    color: var(--v2-text-text-faint);
    user-select: none;
  }

  [data-slot="password-input"][data-invalid]:not([data-disabled])
    [data-slot="password-input-control"],
  [data-slot="password-input-control"]:is(
      [data-invalid],
      [aria-invalid="true"]
    ):not([data-disabled]) {
    color: var(--v2-state-fg-danger);
    caret-color: var(--v2-state-fg-danger);
  }

  [data-slot="password-input"][data-invalid]:not([data-disabled])
    [data-slot="password-input-control"]::placeholder,
  [data-slot="password-input-control"]:is(
      [data-invalid],
      [aria-invalid="true"]
    ):not([data-disabled])::placeholder {
    color: var(--v2-state-fg-danger);
    opacity: 1;
  }

  /* ---------------------------------------------------------------- */
  /* Leading icon                                                     */
  /* ---------------------------------------------------------------- */

  [data-slot="password-input"] > [data-slot="password-input-leading-icon"] {
    display: flex;
    flex: none;
    align-items: center;
    justify-content: center;
    padding-inline-start: 8px;
    color: var(--v2-icon-icon-muted);
  }

  [data-slot="password-input"] > [data-slot="password-input-leading-icon"] svg {
    display: block;
    flex: none;
  }

  /* ---------------------------------------------------------------- */
  /* Visibility toggle — matches input-clear                          */
  /* ---------------------------------------------------------------- */

  [data-slot="password-input-toggle"] {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    align-self: center;
    flex: none;
    width: 20px;
    height: 20px;
    padding: 2px;
    border: 0;
    border-radius: 4px;
    background: transparent;
    color: var(--v2-icon-icon-muted);
    cursor: pointer;
    outline: none;
    transition:
      background 85ms ease-out,
      color 85ms ease-out;
  }

  @media (hover: hover) {
    [data-slot="password-input-toggle"]:hover:not(:disabled, [data-disabled]) {
      background-color: var(--v2-overlay-simple-overlay-hover);
      color: var(--v2-text-text-base);
    }
  }

  [data-slot="password-input-toggle"]:active:not(:disabled, [data-disabled]) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="password-input-toggle"]:focus {
    outline: none;
  }

  [data-slot="password-input-toggle"]:focus-visible {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: 1px;
  }

  [data-slot="password-input"][data-disabled]
    [data-slot="password-input-toggle"] {
    cursor: not-allowed;
    pointer-events: none;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="password-input"],
    [data-slot="password-input-toggle"] {
      transition: none;
    }
  }
}
